func (e *encoder) s_diag_Related(v *diag.Related) {
	e.str(string(v.Path))
	e.int(int64(v.Line))
	e.int(int64(v.Col))
	e.int(int64(v.EndLine))
	e.int(int64(v.EndCol))
	e.str(string(v.Message))
}

func (d *decoder) s_diag_Related(v *diag.Related) {
	v.Path = string(d.str())
	v.Line = int(d.int())
	v.Col = int(d.int())
	v.EndLine = int(d.int())
	v.EndCol = int(d.int())
	v.Message = string(d.str())
}

func (e *encoder) s_lateRef(v *lateRef) {
	e.token(v.tok)
	e.p_Decl(v.entity)
}

func (d *decoder) s_lateRef(v *lateRef) {
	v.tok = d.token()
	v.entity = d.p_Decl()
}
